import{_ as l,o as r,c as o,ag as n}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"공자","slug":"공자","link":"#공자","children":[]},{"level":2,"title":"맹자","slug":"맹자","link":"#맹자","children":[]},{"level":2,"title":"순자","slug":"순자","link":"#순자","children":[]},{"level":2,"title":"묵자","slug":"묵자","link":"#묵자","children":[]},{"level":2,"title":"노자","slug":"노자","link":"#노자","children":[]},{"level":2,"title":"법가","slug":"법가","link":"#법가","children":[]},{"level":2,"title":"음양가 (추연)","slug":"음양가-추연","link":"#음양가-추연","children":[]},{"level":2,"title":"명가 (공손룡)","slug":"명가-공손룡","link":"#명가-공손룡","children":[]},{"level":2,"title":"불교","slug":"불교","link":"#불교","children":[]},{"level":2,"title":"성리학 (주자학)","slug":"성리학-주자학","link":"#성리학-주자학","children":[]},{"level":2,"title":"양명학","slug":"양명학","link":"#양명학","children":[]}],"relativePath":"philosophy/China/10. 시험 용어 정리.md","filePath":"philosophy/China/10. 시험 용어 정리.md"}'),e={name:"philosophy/China/10. 시험 용어 정리.md"};function a(s,t,i,p,g,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<blockquote><p>시험 대비 전체 용어 압축 정리 (공자~양명학).</p></blockquote><h2 id="공자" tabindex="-1">공자 <a class="header-anchor" href="#공자" aria-label="Permalink to &quot;공자&quot;">​</a></h2><p>천하무도 — 질서가 붕괴된 시대, 종법제와 이를 뒷받침하는 예가 존재. 사람은 더불어 살아야 하는 존재 — 사(士)를 군자로 교육.</p><p><strong>인(仁)과 예(禮)</strong>: 인은 사람다움, 충과 서로 나뉨. 예는 인의 실현이자 사회적 규범 — 극기복례. 공자는 &#39;형식적인 예&#39;가 아니라 &#39;내면의 인&#39;을 바탕으로 한 예의 회복을 주장.</p><p><strong>예와 법의 차이</strong>: 둘 다 규범이라는 점에서 비슷한 속성 — 질서유지, 행위의 기준 제공, 공익성 표방.</p><ol><li>규제 대상: 예는 내면의 양심(행위 전 마음가짐), 법은 외면의 행위</li><li>동력: 예는 양심의 부끄러움에 기반, 법은 이기적 공포에 기반</li><li>제재의 방식: 예는 사회적 낙인·관계 단절, 법은 물리적 강제·박탈</li><li>유연성: 예는 때·장소·상대에 따라 유연(중용 추구), 법은 누가 집행해도 같은 결과(일관성)</li></ol><p><strong>종법제도</strong>: 공자가 『주례』를 회복하려 한 이유는 왕권 강화가 아니라 &#39;역할의 규정&#39;을 통한 사회적 혼란 해소.</p><ul><li><strong>정명사상</strong>: 군군신신부부자자 — 각자가 맡은 위치와 역할을 명확히 할 때 사회가 안정됨</li><li>종법적 질서의 내면화로 효와 제가 사회 전체로 확장됨</li></ul><p><strong>군자</strong>, <strong>덕치</strong>: 공동체의 리더가 몸소 도덕적 삶을 살아가는 솔선수범의 정치.</p><h2 id="맹자" tabindex="-1">맹자 <a class="header-anchor" href="#맹자" aria-label="Permalink to &quot;맹자&quot;">​</a></h2><p>인자무적, 덕치 = 인치 = 왕도. 사람은 누구나 불인인지심을 가짐(어린아이가 우물로 기어가는 예시). 측은지심·수오지심·사양지심·시비지심이 각각 인의예지의 단서 — 사단은 성선설의 근거. 패도정치 대신 왕도정치를 주장, 덕을 바탕으로 백성의 마음을 얻어 다스림.</p><p>사람이 타락하는 이유: 1) 시스템의 미비(무항산, 무항심) 2) 수양의 부족(호연지기를 길러야)</p><p>역성혁명: 왕이 왕답지 못하면 교체해야 한다 — 공자의 정명론(군군신신부부자자)과 연결. 맹자는 올바름의 기준을 본성에서 찾음(인간 본성이 선하기 때문).</p><h2 id="순자" tabindex="-1">순자 <a class="header-anchor" href="#순자" aria-label="Permalink to &quot;순자&quot;">​</a></h2><p>성악설, 예를 통해 교화. 천인지분(하늘은 의지 없는 자연법칙). 예는 성인의 실천으로 생기는 것 — 귀천과 나이에 따른 차등을 두어 상황에 맞는 욕망 실현 방법을 정함. 국가를 부국하게 만드는 왕도뿐 아니라 패자도 상대적으로 긍정. 맹자는 백성이 근본, 순자는 군자가 백성의 근본. 순자는 (맹자와 달리) 선의 가능성이 내면에 없다고 보아, 덕치가 아닌 예치를 위해 성인이 그 기준(예)을 만들어야 한다고 봄.</p><h2 id="묵자" tabindex="-1">묵자 <a class="header-anchor" href="#묵자" aria-label="Permalink to &quot;묵자&quot;">​</a></h2><p>왜 살기 힘든가? 전쟁이 나서. 왜 전쟁이 나는가? 별애 해서. 어떻게 해결? 공동체의 이익 증진. 어떻게? 근면한 노동과 알뜰한 소비(절용, 절장).</p><p>친사: 현자를 모으기 위해 높이 대우해야 함 — 능력주의적, 관료의 공공성 강조. 현자를 모아 기준을 통일해야 함(사람마다 올바름의 기준이 달라서). 도덕성의 기준은 공동체의 이익 — 실질적 이익이 없는 도덕은 공허함.</p><p>겸상애 교상리: 공동체에 끼치는 해악이 클수록 큰 벌. 모든 전쟁을 부정하는가? 아님 — 바로잡기 위한 전쟁이나 방어전쟁은 허용(의로움이 아니라 공동체의 이익이 중심이기 때문). 겸상애 교상리는 하늘의 뜻.</p><p>비명(숙명론 비판): 숙명론을 주장하면 근면성실의 동력을 잃음 — 인간의 노력을 무력화하고, 지배층의 무책임을 정당화함.</p><h2 id="노자" tabindex="-1">노자 <a class="header-anchor" href="#노자" aria-label="Permalink to &quot;노자&quot;">​</a></h2><p>도에 따르는 것이 중요 — 도법자연(자연을 본받아야 함). 도는 길을 의미, 곧 우주의 법칙. 인간도 우주에 속한 존재이므로 도에 따라야 함. 자연이란 nature가 아니라 스스로 그러함 — 본래성에 따라 스스로 그렇게 드러나도록 하는 것. 우주에서 자연을 거스르는 존재가 인간 — 있는 그대로가 아닌 개념화를 통해 세계를 받아들이고, 대상을 가치화하여 주관적 가치를 대입 → 좋은 것을 가지려는 욕망에서 갈등과 혼란이 발생.</p><p>도가도 비상도, 명가명 비상명: 말로 표현할 수 있는 도는 도가 아니며, 이름 붙일 수 있는 이름은 영원한 이름이 아님 — 언어는 존재를 온전히 표현할 수 없음. 그럼에도 도라 부르는 이유: 명확히 표현할 수 없어도 어쨌든 표현은 해야 하기 때문.</p><p>도의 성격: 우주만물의 근원, 무규정적, 자연적 질서, 정치와 삶의 기준. 무위의 정치: 아무것도 안 하는 게 아니라 인위적으로 개입하지 않는 것. 소국과민.</p><hr><h2 id="법가" tabindex="-1">법가 <a class="header-anchor" href="#법가" aria-label="Permalink to &quot;법가&quot;">​</a></h2><p>인간의 본성은 이익을 좋아하고 손해를 싫어하므로, 이를 잘 이용해 국가를 다스려야 함. 이기심을 완전히 부정하는 게 아니라, 이익 추구 간의 갈등이 문제 — 이기심을 적절히 실현시키는 것이 목적. 개인의 이기심이 공동체 전체의 이기심 실현으로 이어지는 시스템의 마련과 강력한 적용을 주장. 덕이 있는 현자보다 올바른 법과 제도가 필요.</p><p><strong>한비자</strong>: 상앙의 법·술·세를 종합.</p><p><strong>상앙</strong>: 부국강병 추구. 인간은 이익을 좋아하고 손해를 싫어하는 본성 — 이를 이용해 국가가 원하는 방향으로 유도.</p><ul><li>법은 객관성·투명성·획일적 적용이 되어야 함. 백성이 많아지면 그만큼 문제가 많이 일어나므로 법을 통한 객관적 금지가 필요. 서로가 법을 인식해야 윗사람도 아랫사람을 막 대하지 못하고, 아랫사람도 윗사람의 권리를 침해하지 못함. 사적 관계로 획일적이지 않게 실행되면 사사로운 힘이 법을 이겨 혼란이 생김.</li><li>국가에 중요한 것은 농업과 군사력 — 힘들어도 농업과 전쟁에 나가는 이유는 돈과 명예 때문. 쉽게 돈 버는 상공업을 억제하고, 쉽게 명예를 얻는 학문을 통제 — 농업과 전쟁으로만 이익과 명예를 얻게 함. 철저한 형벌과 포상으로 이를 증진.</li><li>덕치 비판: 어진 사람은 남에게 어질게 대할 수는 있어도, 남을 어질게 만들 수는 없음.</li></ul><h2 id="음양가-추연" tabindex="-1">음양가 (추연) <a class="header-anchor" href="#음양가-추연" aria-label="Permalink to &quot;음양가 (추연)&quot;">​</a></h2><p>음(그늘)과 양(볕)의 개념을 자연세계·인간세계까지 확장. 음과 양은 분리된 개념이지만 공존과 균형을 이루며 세계를 구성.</p><p><strong>천인감응우주론</strong>: 하늘과 인간이 서로 감응 — 오랜 가뭄은 군주가 정치를 잘못했기 때문.</p><p><strong>음양소식</strong>: 음양이 줄고 늘어나는 현상 — 사계절의 교체, 낮과 밤의 교체.</p><p><strong>오행과 음양의 결합</strong>: 본래 음양(양지/음지)과 오행(농업 관련 5종 재료)은 별개 개념이었으나, 점차 한 세트로 묶여 우주론적 운행의 의미를 지니게 됨.</p><p><strong>오덕종시설</strong>: 오덕(목화토금수)이 끝나고 시작하기를 반복 — 왕조의 흥망은 오행의 순환에 따라 일어남. 단순한 자연철학을 넘어 왕조 교체를 정당화하는 정치철학.</p><h2 id="명가-공손룡" tabindex="-1">명가 (공손룡) <a class="header-anchor" href="#명가-공손룡" aria-label="Permalink to &quot;명가 (공손룡)&quot;">​</a></h2><ul><li><strong>백마론</strong>: 흰말은 말이 아님 — &#39;말&#39;은 형체를 명명한 이름, &#39;희다&#39;는 색을 명명한 이름이므로 대상(형체)과 속성(색)은 다름</li><li><strong>견백론</strong>: 단단하고 흰 돌은 몇 개인가? 일상적으로는 사물이 하나의 대상이지만, 인식 차원에서는 (눈은 색만, 손은 단단함만 감각하므로) 여러 성질의 결합체로 나뉨</li><li><strong>통변론</strong>: &quot;둘에 오른쪽이 있는가?&quot; — 명칭 중에는 사물의 속성을 말하는 것 외에, 관계 속에서만 성립하는 명칭(관계어)도 있음</li><li><strong>지물론</strong>: 지시와 지시되는 것은 다름 — 지시 자체는 실재하지 않지만 지시되는 대상은 실재함. 사물과 이름은 완전히 같지도 완전히 다르지도 않음</li></ul><h2 id="불교" tabindex="-1">불교 <a class="header-anchor" href="#불교" aria-label="Permalink to &quot;불교&quot;">​</a></h2><p><strong>브라마니즘과의 차이</strong>: 1) 브라마니즘은 고정된 실체인 아트만을 주장(불교는 무아설) 2) 브라흐만과 아트만이 본래 하나(범아일여)라고 주장(불교는 연기설) 3) 내세의 해탈을 추구(불교는 현세 해탈 가능) 4) 고행주의(불교는 중도)</p><p><strong>12연기 유전문</strong>: 무명(無明)으로 시작해 노사(老死)로 끝나는 12단계가 순차적으로 순환. 고통의 근원은 무명 — 세상에 고정된 실체가 없다는 연기적 진리를 깨달으면 이 순환을 그칠 수 있음.</p><p><strong>무아설과 윤회</strong>: 업을 지은 자와 보를 받는 자는 동일한가? 완전히 같지도 다르지도 않음(불일불이) — 업이 식(識)에 저장되어 상속됨, 마치 촛불이 다른 초로 옮겨붙듯. 과거에 지은 업은 바꿀 수 없지만, 더 이상 새 업을 짓지 않고 지혜를 밝히면 윤회를 끊고 해탈에 이를 수 있음.</p><p><strong>오온·18계</strong>: 인간을 구성하는 5가지 요소(색·수·상·행·식) — 색은 물질적 요소, 수·상·행·식은 정신 작용. 고정된 실체가 있는 게 아니라 이 순간의 연기적 결합이 곧 &#39;나&#39;. 감각기관 기준(안이비설신의, 육입)으로 인식대상(육경)·인식(육식)까지 더하면 인식세계를 구성하는 18가지 요소(18계).</p><p><strong>사성제</strong>: 고집멸도 — 삶은 고통(고), 고통의 원인은 집착/무명(집), 집착을 끊으면 해결 가능(멸), 해결책으로 팔정도 제시(도).</p><p><strong>삼법인</strong>: 제행무상(모든 현상은 변한다), 제법무아(모든 현상에는 고정된 실체가 없다), 일체개고(모든 현상은 고통이다).</p><h2 id="성리학-주자학" tabindex="-1">성리학 (주자학) <a class="header-anchor" href="#성리학-주자학" aria-label="Permalink to &quot;성리학 (주자학)&quot;">​</a></h2><p>북송 5자의 우주론과 인성론을 주희가 결합하여 만든 것이 성리학. 중심 개념은 우주 생성론과 심성 가치론.</p><p><strong>리기이원론</strong>: 주자는 인격신을 부정 — 우주의 보편적 법칙인 <strong>리</strong>와 이를 현실에 구현하는 <strong>기</strong>로 세계를 설명. 리는 스스로 존재하며 원인이 필요 없고 초월적이며 그 자체로 완전하지만, 능동적으로 행위하지 않아 기가 리를 움직이는 방식으로만 활동이 가능함.</p><ul><li>생성론적 관점: 리와 기는 분리되지 않음(<strong>리기불상리</strong>) — 존재물이 생성될 때는 리와 기 사이에 우열이 없음</li><li>가치론적 관점: 생성된 존재물은 선악으로 구분되며 리와 기에 위계가 생김 — 리는 순선, 기는 악의 근원으로 여겨져 분리해서 보아야 함(<strong>리기불상잡</strong>)</li></ul><p><strong>심성론(심·성·정)</strong>: 마음(심)은 성과 정을 포괄함(<strong>심통성정</strong>). 마음의 본질인 성은 리로 존재하며(<strong>성즉리</strong>), 이 성이 기에 의해 밖으로 드러난 것이 정(<strong>성발위정</strong>). 본래 성은 리와 동일하게 선하지만, 기의 움직임에 따라 선한 감정도 악한 감정도 나올 수 있어 훈련을 통해 기가 성을 잘 드러내도록 해야 함.</p><h2 id="양명학" tabindex="-1">양명학 <a class="header-anchor" href="#양명학" aria-label="Permalink to &quot;양명학&quot;">​</a></h2><p>주자학이 종교화되며 학문으로서의 역할을 못하게 됨. 왕양명은 주자의 격물궁리를 듣고 격물을 시도했으나 실패, 리를 마음과 본성에서 찾아야 함을 깨달음 — **심외무사, 심외무리(심즉리)**를 주장.</p><p><strong>즉물궁리 비판</strong>: 주자가 말한 격물을 &#39;즉물궁리&#39;로 표현하며, 마음에서 사물의 리를 구하므로 심과 리가 분리된다고 비판(마음을 인식주체, 물에 내재한 리를 인식대상으로 구분한 것으로 봄).</p><p><strong>격물치지 재해석</strong>: 양명학에서 &#39;격(格)&#39;은 바로잡다로 정의 — 내 마음에 생긴 사사로운 욕망을 바로잡아 제거하고, 본심에 따라 선을 행하는 실천적 행위. 따라서 <strong>치양지</strong>(선한 본심인 양지의 확장)를 주장. 일상에서 양지가 발현되지 않는 것은 개인의 사욕이 양지를 가리기 때문.</p><p><strong>지행합일</strong>: 선지후행(먼저 알고 나중에 행함) 비판 — 앎과 행위는 다른 것이 아니므로, 알면서 행하지 않는 것은 참된 앎이 아님.</p><p><strong>심즉리, 심외무리</strong>: 심즉리는 마음이 곧 리라는 것(이때 마음은 본심, 양지) — 마음과 리를 둘로 나눈 것에 대한 비판. 이는 심외무리(마음 밖에 리가 없음)로 확장되고, 다시 심외무물로 확장됨 — 단, 마음 밖에 객관적 대상이 없다는 주장이 아니라, 내가 의식활동을 하지 않을 때는 의식 대상도 없다는 뜻.</p>',56)])])}const c=l(e,[["render",a]]);export{u as __pageData,c as default};
